class PostModel {
  final bool? success;
  final int? total;
  final int? page;
  final int? limit;
  final int? totalPages;
  final List<CategoryData>? data;

  PostModel({
    this.success,
    this.total,
    this.page,
    this.limit,
    this.totalPages,
    this.data,
  });

  factory PostModel.fromJson(Map<String, dynamic> json) {
    return PostModel(
      success: json['success'],
      total: json['total'] ?? json['totalProducts'],
      page: json['page'],
      limit: json['limit'],
      totalPages: json['totalPages'],
      data: (json['data'] as List?)
          ?.map((e) => CategoryData.fromJson(e))
          .toList(),
    );
  }
}

