class CategoryData {
  final String? id;
  final String? categoryName;
  final String? description;
  final bool? isActive;
  final String? image;
  final bool? show;
  final int? sequence;
  final String? slug;
  final TypeData? type;

  CategoryData({
    this.id,
    this.categoryName,
    this.description,
    this.isActive,
    this.image,
    this.show,
    this.sequence,
    this.slug,
    this.type,
  });

  factory CategoryData.fromJson(Map<String, dynamic> json) {
    // sequence can be int, null, or empty string "" — handle all cases
    int? parseSeq(dynamic v) {
      if (v == null || v == '') return null;
      if (v is int) return v;
      return int.tryParse(v.toString());
    }

    return CategoryData(
      id: json['_id'],
      categoryName: json['categoryName'],
      description: json['description'],
      isActive: json['isActive'],
      image: json['image'],
      show: json['show'],
      sequence: parseSeq(json['sequence']),
      slug: json['slug'],
      type: json['type'] != null ? TypeData.fromJson(json['type']) : null,
    );
  }
}

class TypeData {
  final String? id;
  final String? name;
  final bool? show;

  TypeData({this.id, this.name, this.show});

  factory TypeData.fromJson(Map<String, dynamic> json) {
    return TypeData(id: json['_id'], name: json['name'], show: json['show']);
  }
}

